}

.main-panel {
    flex: 1;
    min-width: 0;
}

.main-panel.expanded {
    flex: 1;
}

.thread-panel-container {
    width: 25%;
    min-width: 280px;
    max-width: 400px;
    flex-shrink: 0;
}

