.message-area {
    display: flex;
    flex-direction: column;
    height: 100%;
    background: #fff;
    overflow: hidden;
}

.area-header {
    display: flex;
    align-items: baseline;
    gap: 0.75rem;
    padding: 0.75rem 1rem;
    border-bottom: 1px solid #e0e0e0;
    flex-shrink: 0;
}

.area-header h3 {
    margin: 0;
    font-size: 1.1rem;
    font-weight: 700;
}

.channel-description {
    font-size: 0.85rem;
    color: #888;
}

.message-list {
    flex: 1;
    overflow-y: auto;
    padding: 0.5rem 0;
}

.load-more {
    text-align: center;
    padding: 0.5rem;
}

.load-more-btn {
    background: none;
    border: 1px solid #ddd;
    border-radius: 6px;
    padding: 0.4rem 1rem;
    font-size: 0.8rem;
    color: #4a76a8;
    cursor: pointer;
    transition: background 0.15s;
}

.load-more-btn:hover:not(:disabled) {
    background: #f0f4f8;
}

.load-more-btn:disabled {
    opacity: 0.5;
    cursor: default;
}

.empty-state {
    display: flex;
    align-items: center;
    justify-content: center;
    height: 100%;
    color: #aaa;
    font-size: 0.95rem;
}

