toolArgs.file_text:
@page "/chat"
@layout ChatLayout
@rendermode InteractiveServer
@using sv_d8c828e3bf0e453aa35e04b36c7f5962.Services
@inject IChatService ChatService

<PageTitle>Chat</PageTitle>

<div class="chat-container">
    <div class="sidebar-panel">
        <ChannelSidebar Channels="_channels"
                        SelectedChannelId="_selectedChannelId"
                        OnChannelSelected="SelectChannel" />
    </div>

    <div class="main-panel @(_isThreadOpen ? "" : "expanded")">
        <MessageArea CurrentChannel="_currentChannel"
                     Messages="_messages"
                     ReplyCounts="_replyCounts"
                     IsLoading="_isLoadingMessages"
                     HasMoreMessages="_hasMoreMessages"
                     OnLoadMore="LoadOlderMessages"
                     OnSendMessage="SendMessage"
                     OnOpenThread="OpenThread"
                     OnReact="AddReaction" />
    </div>

    @if (_isThreadOpen)
    {
        <div class="thread-panel-container">
            <ThreadPanel RootMessage="_threadRootMessage"
                         ThreadMessages="_threadMessages"
                         OnClose="CloseThread"
                         OnSendReply="SendThreadReply" />
        </div>
    }
</div>

@code {
    private const int PageSize = 30;

    private List<Channel> _channels = [];
    private int? _selectedChannelId;
    private Channel? _currentChannel;

    private List<Message> _messages = [];
    private Dictionary<int, int> _replyCounts = [];
    private bool _isLoadingMessages;
    private bool _hasMoreMessages = true;

    private bool _isThreadOpen;
    private Message? _threadRootMessage;
    private List<Message> _threadMessages = [];

    protected override async Task OnInitializedAsync()
    {
        _channels = await ChatService.GetChannelsAsync();
        if (_channels.Count > 0)
        {
            await SelectChannel(_channels[0].Id);
        }
    }

    private async Task SelectChannel(int channelId)
    {
        _selectedChannelId = channelId;
        _currentChannel = _channels.FirstOrDefault(c => c.Id == channelId);
        _messages = [];
        _replyCounts = [];
        _hasMoreMessages = true;
        _isLoadingMessages = true;

        CloseThreadInternal();

        try
        {
            var messages = await ChatService.GetMessagesAsync(channelId, 0, PageSize);
            _messages = messages.Where(m => m.ReplyToId is null).ToList();
            BuildReplyCounts(messages);
            _hasMoreMessages = messages.Count == PageSize;
            await ChatService.MarkChannelReadAsync(channelId);

            // Update unread count locally
            var idx = _channels.FindIndex(c => c.Id == channelId);
            if (idx >= 0)
            {
                _channels[idx] = _channels[idx] with { UnreadCount = 0 };
            }
        }
        finally
        {
            _isLoadingMessages = false;
        }
    }

    private async Task LoadOlderMessages()
    {
        if (_isLoadingMessages || _selectedChannelId is null) return;
        _isLoadingMessages = true;

        try
        {
            var older = await ChatService.GetMessagesAsync(_selectedChannelId.Value, _messages.Count, PageSize);
            var topLevel = older.Where(m => m.ReplyToId is null).ToList();
            _messages.InsertRange(0, topLevel);
            BuildReplyCounts(older);
            _hasMoreMessages = older.Count == PageSize;
        }
        finally
        {
            _isLoadingMessages = false;
        }
    }

    private async Task SendMessage(string content)
    {
        if (_selectedChannelId is null) return;
        var msg = await ChatService.SendMessageAsync(_selectedChannelId.Value, content, null);
        _messages.Add(msg);
    }

    private async Task OpenThread(int rootMessageId)
    {
        _threadRootMessage = _messages.FirstOrDefault(m => m.Id == rootMessageId);
        if (_threadRootMessage is null) return;

        _threadMessages = await ChatService.GetThreadAsync(rootMessageId);
        _isThreadOpen = true;

        // Update reply count
        _replyCounts[rootMessageId] = _threadMessages.Count;
    }

    private void CloseThread()
    {
        CloseThreadInternal();
    }

    private void CloseThreadInternal()
    {
        _isThreadOpen = false;
        _threadRootMessage = null;
        _threadMessages = [];
    }

    private async Task SendThreadReply(string content)
    {
        if (_selectedChannelId is null || _threadRootMessage is null) return;
        var reply = await ChatService.SendMessageAsync(_selectedChannelId.Value, content, _threadRootMessage.Id);
        _threadMessages.Add(reply);
        _replyCounts[_threadRootMessage.Id] = _threadMessages.Count;
    }

    private async Task AddReaction((int MessageId, string Emoji) args)
    {
        await ChatService.AddReactionAsync(args.MessageId, args.Emoji);

        // Optimistically update the local message
        UpdateReactionLocally(_messages, args.MessageId, args.Emoji);
        UpdateReactionLocally(_threadMessages, args.MessageId, args.Emoji);
    }

    private static void UpdateReactionLocally(List<Message> messages, int messageId, string emoji)
    {
        var idx = messages.FindIndex(m => m.Id == messageId);
        if (idx < 0) return;

        var msg = messages[idx];
        var reactions = msg.Reactions.ToList();
        var existing = reactions.FindIndex(r => r.Emoji == emoji);
        if (existing >= 0)
        {
            var r = reactions[existing];
            reactions[existing] = r with { Users = [..r.Users, "You"] };
        }
        else
        {
            reactions.Add(new Reaction(emoji, ["You"]));
        }

        messages[idx] = msg with { Reactions = reactions };
    }

    private void BuildReplyCounts(List<Message> allMessages)
    {
        foreach (var msg in allMessages.Where(m => m.ReplyToId is not null))
        {
            var rootId = msg.ReplyToId!.Value;
            _replyCounts[rootId] = _replyCounts.GetValueOrDefault(rootId) + 1;
        }
    }
}

